
import type { CapabilityRequirementsInput } from './CapabilityRequirementsInput.js';
import type { MoneyMovementBlockedReasonInput } from './MoneyMovementBlockedReasonInput.js';
import type { NextActionInput } from './NextActionInput.js';

/** Merchant capability readiness for a payment or money movement capability. */ export type CapabilityInput = { /** Reasons this capability is blocked, pending, or not available. */ "blocked_reasons"?: Array<MoneyMovementBlockedReasonInput>; /** Flint-owned capability name. Payment capabilities describe transaction acceptance readiness; money movement capabilities describe payout and balance movement readiness. */ "capability": "accept_card_payments" | "save_payment_methods" | "accept_affirm_payments" | "receive_payouts" | "create_standard_payouts" | "manage_payout_destinations" | "manage_payout_settings"; /** Capability domain. API keys scoped to one domain only receive that domain when listing capabilities without a domain filter. */ "domain": "money_movement" | "payments"; /** Actions that can remediate or refresh this capability when Flint can suggest one. */ "next_actions"?: Array<NextActionInput>; /** RFC3339 timestamp for the source state used to evaluate this capability. Format: date-time. */ "observed_at"?: string | globalThis.Date; /** Merchant requirements that affect this capability. */ "requirements": CapabilityRequirementsInput; /** Current readiness status for this capability. */ "status": "ready" | "blocked" | "pending" | "not_available"; };
